seed.push({id:'DEV-074',title:'Keep the workspace usable during refresh failures',area:'Experience',kind:'Bug',status:'Ready to test',priority:'High',release:'MVP',owner:'',due:'',dependencies:'DEV-072, DEV-073',description:'Retain the last loaded workspace during temporary refresh failures, label it as stale and offer retry without discarding open forms.',criteria:'Network/server/malformed responses preserve the existing snapshot.\nShow a stale-data warning and last-loaded timestamp.\n401/403 clear previous workspace content.\nOlder refresh results cannot replace newer results.\nPrevent repeated refresh clicks while loading or saving.',notes:'Response-classification and renewal behavioral tests pass. Visual and browser interaction acceptance remain pending.',version:1,updated:'2026-10-02T02:40:00.000Z'});
molaPlanUpdates.push({id:'DEV-074',patch:{status:'Ready to test',notes:'2026-10-02: Refresh failures now retain the prior workspace with an explicit out-of-date warning, last-loaded timestamp and retry control. Invalid response shapes are rejected before state updates. Access denial clears prior records; expired sessions return to sign-in. Sequence checks discard superseded refresh results. Response and renewal tests pass; no live records or access settings changed. Browser/phone acceptance remains pending.'}});
seed.push({id:'DEV-075',title:'Harden funding approval and revision saves',area:'Approvals',kind:'Bug',status:'Ready to test',priority:'High',release:'MVP',owner:'',due:'',dependencies:'DEV-073',description:'Apply safe save handling to funding revisions and approval rules; repair the detail-panel approval shortcut.',criteria:'Send the current funding token from every approval entry point.\nPrevent rapid duplicate submissions and pending dismissal.\nKeep revision drafts after errors and never automatically replay mutations.\nShow approval failures visibly.\nPreserve all existing server approval rules.',notes:'Actual component-handler tests and server funding regressions pass. No real approvals or policies were changed. Browser/phone acceptance remains pending.',version:1,updated:'2026-10-02T08:15:00.000Z'});
