seed.push({id:'DEV-076',title:'Make weekly dues generation resilient',area:'Contributions',kind:'Bug',status:'Ready to test',priority:'High',release:'MVP',owner:'',due:'',dependencies:'DEV-073',description:'Prevent duplicate generation attempts and require a fresh preview when the result is uncertain.',criteria:'Rapid clicks submit once.\nPreview inputs and schedule edits are disabled while pending.\nFailed or malformed previews clear earlier data.\nAn unconfirmed generation explains records may already exist and requires a fresh preview.\nConfirmed saves report their result before refreshing.',notes:'Weekly-dues component-handler tests and all eight pilot API scenarios pass. Browser/mobile acceptance remains pending.',version:1,updated:'2026-10-02T15:34:00.000Z'});
